parameters.jsCode:
// Settings. For a first run you do not need to change anything here.
//
// The free ReplyNodes endpoints advertise a limit of about 20 requests per minute per IP.
// Each domain makes up to 3 requests to those endpoints (homepage, pricing page, brand data)
// plus one logo check, so a pause of 12 seconds between domains stays under the limit.
return [
  {
    json: {
      mdBase: 'https://md.replynodes.com',
      brandBase: 'https://brand.replynodes.com',
      logoBase: 'https://img.replynodes.com',
      waitSeconds: 12,
      maxHomepageChars: 12000,
      maxPricingChars: 6000,
      maxBrandChars: 3000,
      // Sent as the X-Source header so ReplyNodes can count usage of this template.
      // Delete the header in the HTTP Request nodes if you prefer not to send it.
      sourceHeader: 'n8n-company-research',
    },
  },
];

// Company domains to research: one per line (commas also work).
// Schemes, "www." and paths are removed automatically.
// Entries that are not valid domains are kept in the output with status "failed".
const input = `
stripe.com
linear.app
replynodes.com
`;

function normalize(raw) {
  let s = String(raw || '').trim().toLowerCase();
  if (!s) return null;
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').replace(/^www\./, '');
  s = s.split(/[\/?#]/)[0].replace(/:\d+$/, '');
  const ok = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(s);
  return ok ? s : null;
}

const seen = new Set();
const items = [];
for (const raw of input.split(/[\n,;]+/)) {
  const trimmed = raw.trim();
  if (!trimmed) continue;
  const domain = normalize(trimmed);
  if (domain) {
    if (seen.has(domain)) continue;
    seen.add(domain);
    items.push({ json: { domain, valid: true } });
  } else {
    items.push({ json: { domain: trimmed, valid: false } });
  }
}
return items;

// Reads the homepage Markdown, decides whether it is usable and finds key links.
const domain = $('Loop over domains').item.json.domain;
const settings = $('Settings').first().json;
const res = $json || {};
const statusCode = Number(res.statusCode) || 0;
// n8n 2.x returns the response text in "data", older versions in "body".
const body = typeof res.body === 'string' ? res.body : typeof res.data === 'string' ? res.data : '';
const ok = statusCode >= 200 && statusCode < 300 && body.trim().length >= 200;

const isSiteHost = (host) => host === domain || host === 'www.' + domain || host.endsWith('.' + domain);

// Collect links from Markdown: [text](url)
const candidates = [];
const linkRe = /\[([^\]]*)\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g;
let m;
while ((m = linkRe.exec(body)) !== null) {
  const text = m[1].replace(/[*_`]/g, '').trim();
  const href = m[2].trim();
  if (!href || /^(mailto:|tel:|javascript:|#)/i.test(href)) continue;
  // Small URL resolver (no dependency on the URL global, which Code nodes may not expose).
  let abs = href;
  if (/^\/\//.test(href)) abs = 'https:' + href;
  else if (href.startsWith('/')) abs = 'https://' + domain + href;
  else if (!/^[a-z][a-z0-9+.-]*:/i.test(href)) abs = 'https://' + domain + '/' + href.replace(/^\.\//, '');
  const mm = /^(https?):\/\/([^\/?#:]+)(?::\d+)?([^?#]*)/i.exec(abs);
  if (!mm) continue;
  const host = mm[2].toLowerCase();
  const path = mm[3] || '/';
  candidates.push({ text, href: mm[1].toLowerCase() + '://' + host + path, host, path: path.toLowerCase() });
}

function pick(pathRe, textRe, hostRe) {
  const site = candidates.filter((c) => isSiteHost(c.host));
  const byPath = site.find((c) => pathRe.test(c.path) || (hostRe && hostRe.test(c.host)));
  if (byPath) return byPath;
  return site.find((c) => textRe.test(c.text)) || null;
}

const links = {};
const rules = {
  pricing_url: [/\/(pricing|plans|prices?)(\/|$)/, /^(pricing|plans|plans (&|and) pricing)$/i, null],
  docs_url: [/\/(docs?|documentation|developers?|api)(\/|$)/, /^(docs|documentation|developers?|api( reference| docs)?)$/i, /^(docs|developers?)\./],
  changelog_url: [/\/(changelog|release-notes|releases|whats-new)(\/|$)/, /^(changelog|release notes|what'?s new)$/i, null],
  blog_url: [/\/(blog|news|insights)(\/|$)/, /^(blog|news|insights)$/i, /^blog\./],
  careers_url: [/\/(careers?|jobs|join-us|work-with-us)(\/|$)/, /^(careers?|jobs|we'?re hiring|join us)$/i, /^(careers|jobs)\./],
  contact_url: [/\/(contact|contact-us|contact-sales)(\/|$)/, /^(contact( us| sales)?)$/i, null],
};
for (const [key, [pathRe, textRe, hostRe]] of Object.entries(rules)) {
  const hit = pick(pathRe, textRe, hostRe);
  links[key] = hit ? hit.href : null;
}

// Social profiles can live on other hosts.
const social = {};
const socialRules = [
  ['linkedin', /(^|\.)linkedin\.com$/, /^\/(company|school)\/[^\/]+/],
  ['x', /^(x\.com|twitter\.com|www\.twitter\.com)$/, /^\/(?!intent|share|home|search|i\/)[a-z0-9_]{1,30}\/?$/],
  ['github', /^github\.com$/, /^\/[a-z0-9-]+\/?$/],
  ['youtube', /(^|\.)youtube\.com$/, /^\/(@|channel\/|c\/|user\/)/],
  ['facebook', /(^|\.)facebook\.com$/, /^\/(?!sharer|share)[a-z0-9.\-]+\/?$/],
  ['instagram', /(^|\.)instagram\.com$/, /^\/[a-z0-9_.]+\/?$/],
];
for (const [name, hostRe, pathRe] of socialRules) {
  const hit = candidates.find((c) => hostRe.test(c.host) && pathRe.test(c.path));
  if (hit) social[name] = hit.href;
}

// Where to fetch the pricing page from (host + path for the Markdown endpoint).
let pricingTarget = domain + '/pricing';
if (links.pricing_url) {
  const pm = /^https?:\/\/([^\/]+)(\/.*)?$/i.exec(links.pricing_url);
  if (pm) pricingTarget = pm[1] + (pm[2] || '').replace(/\/+$/, '');
}

return {
  json: {
    domain,
    homepage_status: statusCode,
    homepage_ok: ok,
    homepage_url: 'https://' + domain + '/',
    homepage_markdown: ok ? body.slice(0, Number(settings.maxHomepageChars) || 12000) : '',
    links,
    social_links: social,
    pricing_target: pricingTarget,
  },
};

// Gathers everything fetched for this domain, works out the status and builds the LLM input.
const get = (name) => {
  try {
    return $(name).item.json;
  } catch (e) {
    return null; // that node did not run for this domain
  }
};
const settings = $('Settings').first().json;
const loop = get('Loop over domains') || {};
const domain = loop.domain || null;
const page = get('Parse homepage');
const pricingRes = get('Fetch pricing');
const brandRes = get('Fetch brand');
const logoRes = get('Check logo');

const is2xx = (r) => !!r && Number(r.statusCode) >= 200 && Number(r.statusCode) < 300;
// n8n 2.x returns the response text in "data", older versions in "body".
const bodyOf = (r) => (r && typeof r.body === 'string' ? r.body : r && typeof r.data === 'string' ? r.data : '');

let status = 'ok';
let error = null;
if (loop.valid === false) {
  status = 'failed';
  error = 'invalid_domain';
} else if (!page) {
  status = 'failed';
  error = 'request_failed';
} else if (!page.homepage_ok) {
  const c = page.homepage_status;
  if (c === 429) status = 'rate_limited';
  else if (c === 401 || c === 403 || c === 451) status = 'blocked';
  else if (c >= 200 && c < 300) { status = 'needs_review'; error = 'page_too_short'; }
  else { status = 'failed'; error = c ? 'http_' + c : 'request_failed'; }
}

// Pricing page (optional)
let pricingMd = null;
let pricingPageUrl = null;
if (is2xx(pricingRes) && bodyOf(pricingRes).trim().length >= 200) {
  pricingMd = bodyOf(pricingRes).slice(0, Number(settings.maxPricingChars) || 6000);
  pricingPageUrl = 'https://' + (page ? page.pricing_target : domain + '/pricing');
}

// Brand data (optional). The exact JSON shape is read defensively.
let brand = null;
if (is2xx(brandRes) && bodyOf(brandRes)) {
  try { brand = JSON.parse(bodyOf(brandRes)); } catch (e) { brand = null; }
}
const findKey = (obj, names, depth = 0) => {
  if (!obj || typeof obj !== 'object' || depth > 3) return undefined;
  for (const k of Object.keys(obj)) {
    if (names.includes(k.toLowerCase())) return obj[k];
  }
  for (const k of Object.keys(obj)) {
    const v = typeof obj[k] === 'object' ? findKey(obj[k], names, depth + 1) : undefined;
    if (v !== undefined) return v;
  }
  return undefined;
};
let brandColors = [];
const colorSource = brand ? findKey(brand, ['colors', 'palette', 'color']) : undefined;
if (colorSource !== undefined) {
  const hexes = JSON.stringify(colorSource).match(/#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b/g) || [];
  brandColors = [...new Set(hexes.map((h) => h.toLowerCase()))].slice(0, 6);
}
const brandName = brand ? findKey(brand, ['name', 'companyname', 'brandname', 'title']) : undefined;

// Logo check: the logo endpoint always returns an image, the header tells if it is a real mark.
let logoResolved = null;
if (logoRes && logoRes.headers) {
  const fb = String(logoRes.headers['x-replynodes-logo-fallback'] || '').toLowerCase();
  if (fb === 'logo') logoResolved = true;
  else if (fb === 'placeholder') logoResolved = false;
}

const brandSummary = brand ? JSON.stringify(brand).slice(0, Number(settings.maxBrandChars) || 3000) : '';

const hasContent = status === 'ok';
const llmInput = hasContent
  ? [
      'Domain: ' + domain,
      'Homepage URL: ' + page.homepage_url,
      '',
      '=== HOMEPAGE (Markdown) ===',
      page.homepage_markdown,
      '',
      pricingMd ? '=== PRICING PAGE (' + pricingPageUrl + ') ===\n' + pricingMd : '(No pricing page content was available.)',
      brandSummary ? '\n=== BRAND DATA (JSON, trimmed) ===\n' + brandSummary : '',
    ].join('\n')
  : '';

const evidence = [];
if (page && page.homepage_ok) evidence.push(page.homepage_url);
if (pricingPageUrl) evidence.push(pricingPageUrl);

return {
  json: {
    domain,
    status,
    error,
    has_content: hasContent,
    llm_input: llmInput,
    links: page ? page.links : {},
    social_links: page ? page.social_links : {},
    homepage_url: page ? page.homepage_url : null,
    evidence_urls: evidence,
    pricing_page_url: pricingPageUrl,
    brand_colors: brandColors,
    brand_name: typeof brandName === 'string' ? brandName : null,
    logo_url: domain && loop.valid !== false ? settings.logoBase + '/' + domain : null,
    logo_resolved: logoResolved,
  },
};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "company_name": {
      "type": "string"
    },
    "description": {
      "type": "string"
    },
    "industry": {
      "type": "string",
      "description": "One of: Software / SaaS; Developer tools; AI / Machine learning; Infrastructure / Cloud; Cybersecurity; Fintech / Payments; E-commerce / Retail; Marketing / Advertising; Healthcare / Biotech; Education; Media / Entertainment; Consulting / Services; Manufacturing / Hardware; Travel / Hospitality; Real estate; Non-profit; Other"
    },
