      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "has_free_trial": {
      "type": "string",
      "enum": [
        "yes",
        "no",
        "unknown"
      ]
    },
    "pricing_summary": {
      "type": "string"
    },
    "integrations": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
