    "industry",
    "products",
    "target_customers",
    "has_free_trial",
    "pricing_summary",
    "integrations"
  ]
}

parameters.jsCode:
// Builds the final output row from the collected data and the LLM answer (if any).
const INDUSTRIES = ["Software / SaaS","Developer tools","AI / Machine learning","Infrastructure / Cloud","Cybersecurity","Fintech / Payments","E-commerce / Retail","Marketing / Advertising","Healthcare / Biotech","Education","Media / Entertainment","Consulting / Services","Manufacturing / Hardware","Travel / Hospitality","Real estate","Non-profit","Other"];

const s = $('Collect page data').item.json;
const raw = $json || {};

let llm = null;
if (raw.output && typeof raw.output === 'object') llm = raw.output;
else if (raw.company_name) llm = raw;
else if (typeof raw.text === 'string') {
  try { llm = JSON.parse(raw.text); } catch (e) { llm = null; }
}

const toList = (v, max) => (Array.isArray(v) ? v.map((x) => String(x).trim()).filter(Boolean).slice(0, max) : []);
const toText = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);

let status = s.status;
let error = s.error;
if (s.has_content && !llm) {
  status = 'failed';
  error = 'llm_failed';
}

let companyName = null;
let description = null;
let industry = null;
let products = [];
let targets = [];
let freeTrial = null;
let pricingSummary = null;
let integrations = [];

if (llm) {
  companyName = toText(llm.company_name) || toText(s.brand_name);
  description = toText(llm.description);
  industry = toText(llm.industry);
  if (industry && !INDUSTRIES.includes(industry)) industry = 'Other';
  products = toList(llm.products, 8);
  targets = toList(llm.target_customers, 6);
  const trial = String(llm.has_free_trial || '').toLowerCase();
  freeTrial = trial === 'yes' ? true : trial === 'no' ? false : null;
  pricingSummary = s.pricing_page_url ? toText(llm.pricing_summary) : null;
  integrations = toList(llm.integrations, 10);
  if (status === 'ok' && (!companyName || !description || !industry)) {
    status = 'needs_review';
    error = 'missing_main_fields';
  }
}

return {
  json: {
    domain: s.domain,
    status,
    error,
    company_name: companyName,
    description,
    industry,
    products,
    target_customers: targets,
    has_free_trial: freeTrial,
    pricing_summary: pricingSummary,
    integrations,
    logo_url: s.logo_url,
    logo_resolved: s.logo_resolved,
    brand_colors: s.brand_colors,
    pricing_url: s.pricing_page_url || s.links.pricing_url || null,
    docs_url: s.links.docs_url || null,
    changelog_url: s.links.changelog_url || null,
    blog_url: s.links.blog_url || null,
    careers_url: s.links.careers_url || null,
    contact_url: s.links.contact_url || null,
    social_links: s.social_links,
    source_url: s.homepage_url,
    evidence_urls: s.evidence_urls,
    checked_at: new Date().toISOString(),
  },
};
